function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  let slots = 1;
  let nodes = 0;
  for (const v of root) {
    if (slots === 0) return 'The level-order list has more entries than the tree has child slots.';
    slots--;
    if (v === null) continue;
    if (!Number.isInteger(v) || v < 1 || v > 10000) return 'Each node value is an integer from 1 to 10^4.';
    nodes++;
    slots += 2;
  }
  if (nodes > 100000) return 'The tree has at most 10^5 nodes.';
  return null;
}

