  // Record every node with its depth, parent and original value, then compare all pairs.
  const all = [];
  const walk = (node, depth, parent) => {
    if (!node) return;
    all.push({ node, depth, parent, original: node.val });
    walk(node.left, depth + 1, node);
    walk(node.right, depth + 1, node);
  };
  walk(root, 0, null);
  const totals = all.map(a => all.reduce((sum, b) => sum + (b.depth === a.depth && b.parent !== a.parent ? b.original : 0), 0));
  all.forEach((a, k) => { a.node.val = totals[k]; });
  return root;
}

