function generate(rand, size) {
  const count = size === 'large' ? 990 : 1 + Math.floor(rand() * 10);
  const top = size === 'large' ? 10000 : (rand() < 0.5 ? 9 : 10000);
  const value = () => 1 + Math.floor(rand() * top);
  // Grow a random tree by filling open child slots; a narrow window of recent slots makes it deep.
  const window = rand() < 0.3 ? 3 : Infinity;
  const root = { val: value(), left: null, right: null };
  const open = [[root, 'left'], [root, 'right']];
  for (let made = 1; made < count; made++) {
    const from = Math.max(0, open.length - window);
    const pick = from + Math.floor(rand() * (open.length - from));
    const [parent, side] = open[pick];
    open.splice(pick, 1);
    const child = { val: value(), left: null, right: null };
    parent[side] = child;
    open.push([child, 'left'], [child, 'right']);
  }
  const out = [];
  const queue = [root];
  for (let head = 0; head < queue.length; head++) {
    const node = queue[head];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
